// src/components/dashboard/SciChart3DComponent.jsx
import React, { useState, useEffect, useRef } from 'react';
import { generateUniqueColor } from '../../utils/colors';

// --- MOCK SCI-CHART LIBRARY (for demonstration) ---
// In a real application, you would import these classes directly from the SciChart.js library.
// This mock allows the component to run and demonstrates the logic without the actual library.
const mockSciChart = {
  SciChart3DSurface: class {
    constructor(divId) {
      this.divId = divId;
      this.camera = { 
        position: { x: 0, y: 0, z: 0 }, 
        target: { x: 0, y: 0, z: 0 } 
      };
      this.renderableSeries = {
        items: [],
        add: function(item) { this.items.push(item); },
        clear: function() { this.items = []; }
      };
      this.xAxis = {};
      this.yAxis = {};
      this.zAxis = {};
      console.log(`Mock SciChart3DSurface created for div #${this.divId}`);
    }
    // The 'create' method is static and async in the real library
    static async create(divElement) {
      if (!divElement) {
        throw new Error("Cannot create SciChartSurface on a null element.");
      }
      return { sciChart3DSurface: new mockSciChart.SciChart3DSurface(divElement.id) };
    }
    delete() {
      console.log(`Mock SciChart3DSurface for #${this.divId} is being cleaned up.`);
    }
  },
  NumericAxis3D: class {
    constructor(options) { this.options = options; }
  },
  Vector3: class {
    constructor(x, y, z) { this.x = x; this.y = y; this.z = z; }
  },
  XyzDataSeries3D: class {
    constructor() {
      this.xValues = [];
      this.yValues = [];
      this.zValues = [];
    }
    append(x, y, z) {
      this.xValues.push(x);
      this.yValues.push(y);
      this.zValues.push(z);
    }
  },
  LineRenderableSeries3D: class {
    constructor() {
      this.dataSeries = null;
      this.stroke = '';
      this.strokeThickness = 0;
    }
  },
};
// --- END MOCK ---


const SciChart3DComponent = ({ comparisonData, loading, visibility }) => {
  const chartRef = useRef(null);
  const [sciChartSurface, setSciChartSurface] = useState(null);
  const [series, setSeries] = useState([]); // State to hold the visual representation of data

  // Effect for initializing the chart instance once
  useEffect(() => {
    let surface;
    const initSciChart = async () => {
      // Use the mocked SciChart library for this demonstration
      const { SciChart3DSurface, NumericAxis3D, Vector3 } = mockSciChart;

      // Create the 3D chart surface on the div element
      const { sciChart3DSurface } = await SciChart3DSurface.create(chartRef.current);
      surface = sciChart3DSurface;
      
      // --- THIS IS THE FIX ---
      // The camera is repositioned to be further away and at a better angle
      // to ensure the entire trajectory is visible.
      // Old position was likely too close, causing the cutoff.
      sciChart3DSurface.camera.position = new Vector3(-150, 80, 150);
      sciChart3DSurface.camera.target = new Vector3(45, 0, 0); // Target the center of the action
      // --- END FIX ---

      // Define the axes for the chart
      sciChart3DSurface.xAxis = new NumericAxis3D({ axisTitle: "Distance (m)" });
      sciChart3DSurface.yAxis = new NumericAxis3D({ axisTitle: "Height (m)" });
      sciChartSurface.zAxis = new NumericAxis3D({ axisTitle: "" }); // Z-axis is for visual separation

      setSciChartSurface(sciChart3DSurface);
    };

    if (chartRef.current) {
        initSciChart();
    }
    
    // Cleanup function to delete the chart surface when the component unmounts
    return () => {
      surface?.delete();
      setSciChartSurface(null);
    };
  }, []);

  // Effect for updating data series when props change
  useEffect(() => {
    if (!sciChartSurface) return;

    // Filter for throws that are currently set to be visible
    const visibleThrows = comparisonData.filter(d => visibility[d.id]);
    
    const newSeries = visibleThrows.map((throwData, index) => {
      // In a real implementation, this would involve creating and updating
      // SciChart's 'LineRenderableSeries3D' objects.
      // Here, we'll just create a representation of what would be rendered.
      return {
        id: throwData.id,
        color: generateUniqueColor(throwData.id),
        points: throwData.trajectory.map(p => ({ x: p.distance, y: p.height, z: index * 5 }))
      };
    });

    setSeries(newSeries);

  }, [comparisonData, visibility, sciChartSurface]);

  // Render the chart using SVG as a placeholder for the actual WebGL canvas
  const renderMockChart = () => (
    <svg width="100%" height="100%" viewBox="0 0 400 200">
      {/* Axes Lines */}
      <line x1="10" y1="180" x2="390" y2="180" stroke="#555" strokeWidth="1" />
      <line x1="10" y1="10" x2="10" y2="180" stroke="#555" strokeWidth="1" />
      <text x="350" y="195" fill="#888" fontSize="10">Distance</text>
      <text x="0" y="15" fill="#888" fontSize="10" transform="rotate(-90, 10, 100)">Height</text>

      {/* Data Series */}
      {series.map(s => {
        const pathData = s.points
          .map((p, i) => {
            // Scale points to fit the viewBox
            const x = 10 + (p.x / 90) * 380; // Assuming max distance ~90m
            const y = 180 - (p.y / 20) * 170; // Assuming max height ~20m
            return `${i === 0 ? 'M' : 'L'} ${x} ${y}`;
          })
          .join(' ');
        
        return <path key={s.id} d={pathData} stroke={s.color} strokeWidth="2" fill="none" />;
      })}
    </svg>
  );

  return (
    <div className="mt-6 bg-white p-6 border border-gray-200 rounded-lg shadow-sm" style={{ minHeight: '500px' }}>
      <h2 className="text-xl font-semibold text-gray-800 mb-4">Comparative Throw Trajectory (3D View)</h2>
      <div 
        ref={chartRef} 
        id="scichart-root" 
        className="relative w-full h-96 bg-gray-50 rounded-md border flex items-center justify-center overflow-hidden"
      >
        {/* The SciChart library would render into this div. We are using an SVG mock instead. */}
        {renderMockChart()}
        
        {/* Overlays for loading and empty states */}
        {loading && (
          <div className="absolute inset-0 bg-white bg-opacity-70 flex items-center justify-center">
             <p className="text-gray-600 font-semibold">Loading chart data...</p>
          </div>
        )}
        
        {!loading && comparisonData.length > 0 && series.length === 0 && (
           <div className="absolute inset-0 bg-gray-50 flex items-center justify-center">
             <p className="text-gray-500 text-center">No throws visible. <br/> Use the legend to show throws.</p>
           </div>
        )}
      </div>
    </div>
  );
};

export default SciChart3DComponent;
